// Liveness: every other tile reads NONE on an empty range, which is also what a
// stopped collector looks like. -1 is the sentinel for "no TCP flows at all".
seen = from(bucket: "network_traffic")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "network_flow" and r.protocol == "6" and r._field == "syn_packets" and r._value > 0)
  |> filter(fn: (r) => r.src_ip =~ cidrRe or r.dst_ip =~ cidrRe)
  |> group()
  |> count()
  |> keep(columns: ["_value"])

union(tables: [seen, array.from(rows: [{_value: -1}])])
  |> group()
  |> max()

