// Which services the candidates probed, by distinct source: a service many
// scanners try is what the network is being searched for.
from(bucket: "network_traffic")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "network_flow" and r.protocol == "6" and r._field == "syn_packets" and r._value > 0)
  |> filter(fn: (r) => r.src_ip =~ /^${scanners:regex}$/)
  |> filter(fn: (r) => r.src_ip =~ cidrRe or r.dst_ip =~ cidrRe)
  |> group(columns: ["service", "dst_ip"])
  |> count()
  |> group(columns: ["service"])
  |> count()
  |> group()
  |> sort(columns: ["_value"], desc: true)
  |> limit(n: 15)
  |> rename(columns: {_value: "targets"})
  |> keep(columns: ["service", "targets"])

