// ICMP host discovery: one source, many destinations, nothing else.
from(bucket: "network_traffic")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "network_flow" and r.protocol == "1" and r._field == "packets")
  |> filter(fn: (r) => r.src_ip =~ cidrRe or r.dst_ip =~ cidrRe)
  |> group(columns: ["src_ip", "dst_ip"])
  |> count()
  |> group(columns: ["src_ip"])
  |> count()
  |> group()
  |> filter(fn: (r) => r._value >= 20)
  |> sort(columns: ["_value"], desc: true)
  |> limit(n: 25)
  |> rename(columns: {_value: "targets"})
  |> keep(columns: ["src_ip", "targets"])

import "regexp"
import "strings"

// Turn the CIDR filter box into an anchored prefix regex. Kept as a regex because that
// is the only form InfluxDB pushes down to storage; mask arithmetic per record
// times out on a busy mirror. Prefix lengths other than /8, /16, /24 and /32
// round DOWN to the enclosing octet boundary, so the range can be wider than
// typed (/20 behaves as /16) -- it never hides matching traffic.
// The split sits in the else branch on purpose: an empty box has no octets to
// index, and Flux evaluates a block's statements eagerly.
cidrPrefix = (cidr) => {
    p = strings.split(v: cidr, t: "/")
    bits = if length(arr: p) > 1 then int(v: p[1]) else 32
    o = strings.split(v: p[0], t: ".")

    return
        if bits <= 8 then "^" + o[0] + "\\."
        else if bits <= 16 then "^" + o[0] + "\\." + o[1] + "\\."
        else if bits <= 24 then "^" + o[0] + "\\." + o[1] + "\\." + o[2] + "\\."
        else "^" + o[0] + "\\." + o[1] + "\\." + o[2] + "\\." + o[3] + "$"
}

// An empty box means no filtering.
cidrRe = if "${cidr}" == "" then /.*/ else regexp.compile(v: cidrPrefix(cidr: "${cidr}"))

// One source, so a pivot is affordable here: every attempt with its port and
// how the target answered. 1 packet = no answer (filtered or host down); a
// RST back = closed; 3 or more packets = the SYN was answered, i.e. open.
from(bucket: "network_traffic")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "network_flow" and r.protocol == "6" and r.src_ip == "${scanner}")
  |> filter(fn: (r) => r._field == "dst_port" or r._field == "packets" or r._field == "syn_packets" or r._field == "rst_packets")
  |> filter(fn: (r) => r.dst_ip =~ cidrRe or r.src_ip =~ cidrRe)
  |> pivot(rowKey: ["_time"], columnKey: ["_field"], valueColumn: "_value")
  |> filter(fn: (r) => r.syn_packets > 0)
  |> map(fn: (r) => ({r with
      open: if r.packets >= 3 then 1 else 0,
      closed: if r.packets < 3 and r.rst_packets > 0 then 1 else 0,
      silent: if r.packets < 3 and r.rst_packets == 0 then 1 else 0}))
  |> group(columns: ["dst_port", "service"])
  |> reduce(identity: {attempts: 0, open: 0, closed: 0, silent: 0}, fn: (r, accumulator) => ({
      attempts: accumulator.attempts + 1,
      open: accumulator.open + r.open,
      closed: accumulator.closed + r.closed,
      silent: accumulator.silent + r.silent}))
  |> group()
  |> sort(columns: ["open", "attempts"], desc: true)
  |> limit(n: 200)
  |> keep(columns: ["dst_port", "service", "attempts", "open", "closed", "silent"])

